// single-item input: the config node emits exactly one row.
const cfg = $input.first().json;

const topics = String(cfg.topics || '')
  .split(',')
  .map((t) => t.trim())
  .filter(Boolean);

if (!topics.length) {
  throw new Error('Add at least one topic to search in ' + 'Set Topic Config' + '.');
}

// The discovery schema is {search_keyword, country}, and country is both
// optional and fussy - it rejected US, us, USA and United States, and accepted
// only an empty string - so it is left out rather than exposed as a setting
// that would fail for whoever filled it in.
const payload = topics.map((search_keyword) => ({ search_keyword }));

return [{ json: { payload, topics, scanned_at: new Date().toISOString() } }];

// single-item input: the trigger endpoint answers once with one snapshot id.
const res = $input.first().json;

// Bright Data answers validation errors with HTTP 200 and an error body, and
// this node runs with neverError, so an unchecked response looks like a success
// and fails several nodes later blaming the wrong thing.
if (res.error || res.errors) {
  throw new Error('Bright Data rejected the search: ' + JSON.stringify(res.error || res.errors));
}
if (!res.snapshot_id) {
  throw new Error('No snapshot_id in the Bright Data response: ' + JSON.stringify(res).slice(0, 400));
}

return [{ json: { snapshot_id: res.snapshot_id } }];

// Eight posts took 82 seconds in testing, the fastest dataset in this set.
// 20 x 15s is five minutes, which covers several topics at the default count.
const MAX_POLLS = 20;

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check Scrape Accepted').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'Snapshot ' + snapshotId + ' still ' + res.status + ' after ' + attempt +
    ' polls. Raise MAX_POLLS, search fewer topics, or lower posts_per_topic.'
  );
}

return [{ json: { status: res.status, snapshot_id: snapshotId, attempt, records: res.records || 0 } }];

const cfg = $('Set Topic Config').first().json;
const minPlays = Number(cfg.min_plays) || 0;
const minPosts = Math.max(Number(cfg.min_posts_per_tag) || 3, 2);
const minLift = Number(cfg.min_lift) || 1.2;

const median = (arr) => {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

const round = (n, places) => {
  const f = Math.pow(10, places);
  return Math.round(n * f) / f;
};

// Reach tags carry no topical meaning - every account in every niche uses them,
// so they always look popular and never tell you what to make. Dropping them is
// the difference between a list of tags and a list of #fyp.
const REACH_TAGS = new Set([
  'fyp', 'fypage', 'foryou', 'foryoupage', 'viral', 'viralvideo', 'trending',
  'tiktok', 'parati', 'paratii', 'xyzbca', 'explore', 'explorepage', 'follow',
  'like', 'trend', 'fy', 'capcut',
]);

const DAY = 86400000;
const seen = new Set();
const posts = [];

for (const item of $input.all()) {
  const j = item.json;
  if (j.error || j.warning) continue;

  const id = String(j.post_id || j.shortcode || '');
  if (!id || seen.has(id)) continue;
  seen.add(id);

  const plays = Number(j.play_count) || 0;
  // Below a floor of plays the engagement rate is a coin flip - one like on
  // twenty views reads as 5%, which would outrank a post that reached a million.
  if (plays < minPlays) continue;

  const likes = Number(j.digg_count) || 0;
  const comments = Number(j.comment_count) || 0;
  // `share_count` is a string and `num_share_count` is the same number as an
  // integer, so the integer is preferred and the string is the fallback.
  const shares = Number(j.num_share_count != null ? j.num_share_count : j.share_count) || 0;
  const saves = Number(j.collect_count) || 0;

  const posted = Date.parse(String(j.create_time || ''));
  const tags = (j.hashtags || [])
    .map((t) => String(t || '').toLowerCase().replace(/^#/, '').trim())
    .filter((t) => t.length > 1 && t.length < 40 && !REACH_TAGS.has(t));

  posts.push({
    post_id: id,
    topic: String((j.discovery_input && j.discovery_input.search_keyword) || '').trim(),
    url: String(j.url || ''),
    description: String(j.description || '').replace(/\s+/g, ' ').trim(),
    account: String(j.profile_username || j.account_id || '').trim(),
    followers: Number(j.profile_followers) || 0,
    region: String(j.region || '').trim(),
    plays,
    likes,
    comments,
    shares,
    saves,
    // Everything a viewer can do deliberately, over everything that was merely
    // shown. Saves and shares are in here because on how-to content they are
    // the whole point, and they routinely outrun likes.
    engagement_rate: plays ? round(((likes + comments + shares + saves) / plays) * 100, 2) : 0,
    saves_per_1k: plays ? round((saves / plays) * 1000, 1) : 0,
    duration: Number(j.video_duration) || 0,
    posted_on: isNaN(posted) ? '' : new Date(posted).toISOString().slice(0, 10),
    age_days: isNaN(posted) ? 0 : Math.round((Date.now() - posted) / DAY),
    sound: String(j.original_sound || '').trim(),
    tags,
  });
}

if (!posts.length) {
  throw new Error(
    'No posts came back above ' + minPlays + ' plays. Lower min_plays, widen ' +
    'the topics, or raise posts_per_topic.'
  );
}

// --- each topic is its own baseline -----------------------------------------
// Comparing a cooking hashtag against a software one would only tell you which
// niche is busier. The question is which tag beats the topic it sits in.
const byTopic = {};
for (const p of posts) (byTopic[p.topic] = byTopic[p.topic] || []).push(p);

const rows = [];
let examined = 0;
// Tags that appeared but on too few posts to say anything about. Reported
// rather than dropped quietly, because on a narrow search it is most of them.
let thinTags = 0;

for (const [topic, group] of Object.entries(byTopic)) {
  const baseline = median(group.map((p) => p.engagement_rate));
  if (!baseline) continue;
  examined += group.length;

  const buckets = {};
  const put = (kind, name, post) => {
    if (!name) return;
    const key = kind + '||' + name;
    (buckets[key] = buckets[key] || { kind, name, posts: [] }).posts.push(post);
  };

  for (const p of group) {
    for (const t of p.tags) put('hashtag', t, p);
    put('sound', p.sound, p);
  }

  for (const b of Object.values(buckets)) {
    if (b.posts.length < minPosts) {
      thinTags += 1;
      continue;
    }

    const rate = median(b.posts.map((p) => p.engagement_rate));
    const lift = round(rate / baseline, 2);
    if (lift < minLift) continue;

    const best = [...b.posts].sort((a, b2) => b2.engagement_rate - a.engagement_rate);

    rows.push({
      topic,
      kind: b.kind,
      // The key the sheet dedupes on. A tag is only the same tag inside the
      // same topic, because its lift is measured against that topic's median.
      tag_key: topic + '|' + b.kind + '|' + b.name,
      name: b.name,
      label: b.kind === 'hashtag' ? '#' + b.name : b.name,
      post_count: b.posts.length,
      topic_post_count: group.length,
      median_engagement: round(rate, 2),
      topic_median_engagement: round(baseline, 2),
      lift,
      median_plays: median(b.posts.map((p) => p.plays)),
      median_duration: median(b.posts.map((p) => p.duration)),
      median_saves_per_1k: round(median(b.posts.map((p) => p.saves_per_1k)), 1),
      // Search results are ranked by relevance, not date, so the age range is
      // reported rather than assumed. Calling any of this "trending" would be
      // a claim the data does not support.
      newest_days: Math.min(...b.posts.map((p) => p.age_days)),
      oldest_days: Math.max(...b.posts.map((p) => p.age_days)),
      accounts: [...new Set(b.posts.map((p) => p.account))].slice(0, 5),
      top_post_url: best[0].url,
      top_post_plays: best[0].plays,
      // The three best posts under this tag, which is what the model reads to
      // name the format. Descriptions come back in whatever language the poster
      // wrote in, so the model is told to answer in English regardless.
      sample_text: best
        .slice(0, 3)
        .map((p) => p.description.slice(0, 220))
        .filter((t) => t.length > 10)
        .join(' || ')
        .slice(0, 700),
    });
  }
}

if (!examined) {
  throw new Error(
    'No topic had a usable engagement baseline. Raise posts_per_topic so each ' +
    'topic comes back with enough posts to take a median of.'
  );
}

if (!rows.length) {
  throw new Error(
    examined + ' posts were examined and no hashtag or sound appeared on ' +
    minPosts + ' or more of them at ' + minLift + 'x the topic median. Lower ' +
    'min_lift or min_posts_per_tag, or raise posts_per_topic.'
  );
}

// Stamped after the loop so every row carries the final counts.
for (const r of rows) {
  r.examined = examined;
  r.thin_tags = thinTags;
}

return rows.sort((a, b) => b.lift - a.lift).map((json) => ({ json }));

const cfg = $('Set Topic Config').first().json;
const limit = Number(cfg.tags_per_run) || 6;
const cooldownDays = Number(cfg.revisit_after_days) || 30;

// The sheet read runs with alwaysOutputData, so on the very first run this is a
// single empty item rather than no items. Treat that as "nothing logged yet"
// instead of letting an undefined row through as a real record.
const logged = $input.all()
  .map((i) => i.json || {})
  .filter((r) => r && r.tag_key);

const cutoff = Date.now() - cooldownDays * 86400000;
const recent = new Set(
  logged
    .filter((r) => {
      const t = Date.parse(String(r.logged_at || ''));
      // A row with an unreadable date still counts as logged. Treating it as
      // fair game would put the same tag back in the digest every week.
      return isNaN(t) ? true : t >= cutoff;
    })
    .map((r) => String(r.tag_key))
);

const scored = $('Score Hashtag Lift').all().map((i) => i.json);
const fresh = scored.filter((r) => !recent.has(String(r.tag_key)));

// A week where every tag was already reported is a normal outcome, not an
// error. Returning nothing would end the branch here and the IF below would
// never run, so nothing would mark the run as finished - hence one marker item
// with no tag_key, which routes to the quiet branch.
if (!fresh.length) {
  return [{
    json: {
      no_new_tags: true,
      examined: scored.length ? scored[0].examined : 0,
      already_logged: scored.length,
    },
  }];
}

return fresh.slice(0, limit).map((json) => ({ json }));

parameters.text:
=Read the captions from the best performing posts under one TikTok tag and say what kind of content it is.

Answer in English even when the captions are not in English, and describe only
what the captions show. If they are too short or too garbled to tell, set
`is_readable` to false and leave the other fields empty rather than guessing.

`content_format` is how the video is built: tutorial, demo, result, listicle,
opinion, story, or promo.
`angle` is one short sentence naming what the posts promise the viewer.
`topics` are two to four plain lower case noun phrases.

Tag: {{ $json.label }}
Topic it was found under: {{ $json.topic }}
Posts using it: {{ $json.post_count }}
Accounts posting it: {{ ($json.accounts || []).join(', ') }}

Captions from its three best posts:
{{ $json.sample_text || 'none' }}

parameters.jsonSchemaExample:
{
  "content_format": "tutorial | demo | result | listicle | opinion | story | promo",
  "angle": "what these posts promise the viewer, in one sentence",
  "topics": [
    "workflow automation",
    "lead generation"
  ],
  "is_readable": true
}

parameters.jsCode:
const cfg = $('Set Topic Config').first().json;
const picks = $('Select New Tags').all().map((i) => i.json);
// The extractor nests its result under `output` on some versions. Reading the
// item directly gives undefined formats on every tag, which produces an empty
// digest on a run where every node is green.
const read = $input.all().map((i) => (i.json && i.json.output) || i.json || {});

// The model ignores the enum often enough to plan for - across earlier
// templates it answered "in-office" and "very negative" to fixed-value schemas.
// Left unnormalised these become extra categories in the sheet.
const FORMAT = (v) => {
  const t = String(v || '').toLowerCase();
  if (/tutorial|how.?to|guide|step/.test(t)) return 'tutorial';
  if (/demo|walkthrough|build|showcase/.test(t)) return 'demo';
  if (/result|case|proof|number/.test(t)) return 'result';
  if (/listicle|list|top \d|roundup/.test(t)) return 'listicle';
  if (/opinion|take|rant|advice/.test(t)) return 'opinion';
  if (/story|journey|narrative/.test(t)) return 'story';
  if (/promo|ad|sales|offer/.test(t)) return 'promo';
  return 'unclear';
};

const clean = (s, max) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, max);

// The extractor emits one item per input item in the same order, so index
// alignment is the join key.
const rows = picks.map((r, i) => {
  const x = read[i] || {};
  const readable = x.is_readable !== false;
  const topics = (readable ? (x.topics || []) : [])
    .map((t) => String(t || '').toLowerCase().trim())
    .filter((t) => t.length > 2 && t.length < 45)
    .slice(0, 4);

  const format = readable ? FORMAT(x.content_format) : 'unclear';

  // The line is assembled from measured fields plus the format the model read
  // out of the captions. Nothing here is the model's opinion of whether the tag
  // is worth using, which is what keeps every clause checkable.
  const takeaway =
    `${r.label}: ${r.lift}x the topic median engagement across ` +
    `${r.post_count} posts, ${r.median_engagement}% against ${r.topic_median_engagement}%` +
    (format !== 'unclear' ? `, mostly ${format} posts` : '') +
    `, median length ${r.median_duration}s.`;

  return {
    ...r,
    content_format: format,
    angle: clean(readable ? x.angle : '', 200),
    content_topics: topics,
    takeaway,
  };
});

const tally = (key) => {
  const m = {};
  for (const r of rows) for (const v of [].concat(r[key] || [])) {
    if (v) m[v] = (m[v] || 0) + 1;
  }
  return Object.entries(m).sort((a, b) => b[1] - a[1]).map(([name, count]) => ({ name, count }));
};

const ages = rows.flatMap((r) => [r.newest_days, r.oldest_days]);

return [{
  json: {
    scanned_at: new Date().toISOString().slice(0, 10),
    topics: cfg.topics,
    // How many posts were examined, not how many tags made the list.
    examined_count: Number($('Score Hashtag Lift').first().json.examined) || 0,
    // The bar a tag had to clear, so the digest can name it rather than saying
    // "above the median", which is only true while min_lift is exactly 1.
    min_lift: Number(cfg.min_lift) || 1.2,
    thin_tag_count: Number($('Score Hashtag Lift').first().json.thin_tags) || 0,
    // Everything over the lift threshold, which is not the same as everything
    // described - tags_per_run caps the second number.
    scored_count: $('Score Hashtag Lift').all().length,
    listed_count: rows.length,
    hashtag_count: rows.filter((r) => r.kind === 'hashtag').length,
    sound_count: rows.filter((r) => r.kind === 'sound').length,
    // TikTok search ranks on relevance, not date, so the digest states how old
    // the posts behind these numbers actually are.
    newest_days: ages.length ? Math.min(...ages) : 0,
    oldest_days: ages.length ? Math.max(...ages) : 0,
    common_formats: tally('content_format').slice(0, 5),
    common_topics: tally('content_topics').slice(0, 5),
    tags: rows,
  },
}];

parameters.text:
=You are a content strategist deciding how to tag and frame the next batch of TikTok posts for a niche.

Topics searched: {{ $json.topics }}
Posts examined: {{ $json.examined_count }}
Tags and sounds in front of you: {{ $json.listed_count }}
Of those, hashtags: {{ $json.hashtag_count }} and sounds: {{ $json.sound_count }}
Content formats behind them: {{ JSON.stringify($json.common_formats) }}
What the posts are about: {{ JSON.stringify($json.common_topics) }}
The posts behind these numbers were published between {{ $json.newest_days }} and {{ $json.oldest_days }} days ago.
The tags themselves: {{ JSON.stringify($json.tags.map(t => ({ tag: t.label, kind: t.kind, lift: t.lift, engagement: t.median_engagement, topic_median: t.topic_median_engagement, posts: t.post_count, plays: t.median_plays, seconds: t.median_duration, saves_per_1k: t.median_saves_per_1k, format: t.content_format, angle: t.angle }))) }}

Write 4 to 6 sentences covering: which tag or sound is worth using first and why, what the winning posts have in common, and what the median length and save rate say about the format to make.

Lift is measured against the median engagement of the same topic's own search results, so say "beats the topic median" rather than "is trending". TikTok search ranks on relevance rather than date and the posts here are months old, so never describe any of this as happening right now. These are the top few tags, not all of them, so write about "the tags here" and never state how many cleared the threshold in total. Plain sentences, no bullet points, no headings.

parameters.jsCode:
const data = $('Rank Hashtags').first().json;
// single-item input: the brief chain is fed one aggregated item and answers with
// one block of prose, so there is no second item to lose here.
const brief = String($input.first().json.text || $input.first().json.output || '').trim();

const plural = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');

// One row per tag, so the sheet doubles as the do-not-repeat list the next run
// reads back.
const rows = data.tags.map((t) => ({
  logged_at: data.scanned_at,
  tag_key: t.tag_key,
  kind: t.kind,
  tag: t.label,
  topic: t.topic,
  lift: t.lift,
  median_engagement: t.median_engagement,
  topic_median_engagement: t.topic_median_engagement,
  post_count: t.post_count,
  topic_post_count: t.topic_post_count,
  median_plays: t.median_plays,
  median_duration: t.median_duration,
  median_saves_per_1k: t.median_saves_per_1k,
  newest_days: t.newest_days,
  oldest_days: t.oldest_days,
  content_format: t.content_format,
  angle: t.angle,
  content_topics: t.content_topics.join('; '),
  accounts: t.accounts.join('; '),
  top_post_plays: t.top_post_plays,
  top_post_url: t.top_post_url,
  takeaway: t.takeaway,
}));

const held = data.scored_count - data.listed_count;
const lines = [];
lines.push('*TikTok tags worth using*');
lines.push(
  `${plural(data.examined_count, 'post')} examined, ` +
  `${plural(data.scored_count, 'tag')} at ${data.min_lift}x the topic median or better` +
  // Saying which of the two numbers the list below shows, so a capped run does
  // not read as though only that many tags cleared the threshold.
  (held > 0 ? `, top ${data.listed_count} here.` : '.')
);
lines.push(
  `Posts behind these numbers are ${data.newest_days} to ${data.oldest_days} ` +
  'days old - TikTok search ranks on relevance, not date.'
);

lines.push('');
data.tags.slice(0, 8).forEach((t, i) => {
  lines.push(`${i + 1}. *${t.label}* (${t.kind}) - ${t.lift}x topic median`);
  lines.push(
    `   ${t.median_engagement}% engagement vs ${t.topic_median_engagement}% | ` +
    `${t.post_count} posts | ${t.median_duration}s median | ` +
    `${t.median_saves_per_1k} saves per 1k views`
  );
  if (t.angle) lines.push(`   ${t.content_format}: ${t.angle}`);
  lines.push(`   Best post: ${t.top_post_url}`);
});

if (data.common_formats.length) {
  lines.push('');
  lines.push('*Formats behind the list*');
  lines.push(data.common_formats.map((f) => `${f.name} (${f.count})`).join(', '));
}

if (data.thin_tag_count) {
  lines.push('');
  lines.push(
    `${plural(data.thin_tag_count, 'tag')} appeared on too few posts to measure ` +
    'and were left out.'
  );
}

if (brief) {
  lines.push('');
  lines.push(brief);
}

// One item carrying both payloads. Split Out turns `rows` into one item per tag
// for the sheet; the Slack node runs once and reads `message` from here.
// Emitting the message as its own item instead would append it to the sheet as
// a row, and post the digest once per tag.
return [{ json: { message: lines.join('\n'), rows, row_count: rows.length } }];
